using System;using System.IO;using System.Linq;using System.Reflection;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;using System.Web.Script.Serialization;

// File/fixture tests only. Never calls EngineSession.Start or the real USB factory.
static class PublicTests {
 public static int Run(string root,string official){
  root=Path.GetFullPath(root);string folder=Path.Combine(root,"build","public-tests");Directory.CreateDirectory(folder);UiText.Select("es");StudioUsbGate.UseTestLock(Path.Combine(folder,"fixture-device.lock"));Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
  var cases=new List<object>();int failed=0;Action<bool> need=b=>{if(!b)throw new Exception("Assertion failed");};Action<string,Action> test=(name,body)=>{try{body();cases.Add(new{name=name,status="PASS"});}catch(Exception e){failed++;cases.Add(new{name=name,status="FAIL",error=e.ToString()});}};
  string source=Path.Combine(root,"models","Developed by Conr4d.nam"),namFolder=Path.Combine(folder,"nam");Directory.CreateDirectory(namFolder);File.Copy(Path.Combine(root,"tests","default-carrier.wav"),Path.Combine(namFolder,"expected.wav"),true);
  test("nam_converter_and_transport_fixtures_33_cases",()=>need(NamTests.Run(source,namFolder)==0));
  test("normal_startup_is_firmware_without_sdk_or_usb",()=>{using(var w=new StudioWindow(false)){need(w.FirmwareVisible&&!w.InstallEnabled&&!w.IsBusy&&StudioUsbGate.Owner==""&&PortableRuntime.Root==null);need(w.SelectSectionAsync(false).GetAwaiter().GetResult()&&!w.FirmwareVisible&&StudioUsbGate.Owner=="");}});
  test("english_and_spanish_headings_and_backup_notice",()=>{foreach(string lang in new[]{"es","en"}){UiText.Select(lang);using(var w=new StudioWindow(true)){string expected=lang=="en"?"Firmware and recovery":"Firmware y recuperaci\u00f3n";need(Children(w).OfType<Label>().Any(c=>c.Text==expected));var notice=InstallNotice.For(new FirmwareFile());need(notice.Icon==MessageBoxIcon.Warning&&notice.Text.Contains(lang=="en"?"create a backup":"realiza un backup"));var picker=Children(w).OfType<ComboBox>().Single(c=>c.Name=="InterfaceLanguage");need(picker.SelectedIndex==(lang=="en"?1:0));}}UiText.Select("es");});
  test("backup_cancel_never_dispatches_to_the_engine",()=>{using(var pane=new StudioFirmwarePane(false)){var engine=new EngineSession(s=>{},()=>{},p=>{});Field(engine,"running",true);Field(engine,"selectionReady",true);Field(engine,"selectedId",FirmwareFile.Product);Field(pane,"engine",engine);Call(pane,"ShowFirmware",new FirmwareFile{Hash=PortableRuntime.CustomHash});byte[] b=new byte[128];Buffer.BlockCopy(BitConverter.GetBytes(0x4c364641U),0,b,0,4);Buffer.BlockCopy(BitConverter.GetBytes(FirmwareFile.Product),0,b,24,4);string path=Path.Combine(folder,"synthetic-backup.pgb");File.WriteAllBytes(path,b);Call(pane,"SetBackup",path);need(pane.InstallEnabled);int writes=0;Call(pane,"RequestInstall",new Func<InstallNotice,bool>(n=>false),new Action<FirmwareFile,string>((f,p)=>writes++));need(writes==0);}});
  test("recipe_embedded_without_vendor_runtime_archive",()=>{var names=Assembly.GetExecutingAssembly().GetManifestResourceNames();need(names.Contains("patch.json")&&names.Contains("en.json")&&!names.Contains("runtime.zip"));});
  if(official!=null){
   byte[] patch;using(var input=Assembly.GetExecutingAssembly().GetManifestResourceStream("patch.json"))using(var m=new MemoryStream()){input.CopyTo(m);patch=m.ToArray();}
   test("public_patch_rebuilds_all17_images_and_exact_v8_payload",()=>{var original=FirmwareFile.Read(official);need(original.IsOfficial);byte[] rebuilt=PublicFirmware.Apply(File.ReadAllBytes(official),patch);string file=Path.Combine(folder,"rebuilt.hxf");File.WriteAllBytes(file,rebuilt);var checkedFile=FirmwareFile.Read(file);need(PortableRuntime.IsCustom(checkedFile)&&checkedFile.ImageCount==17&&FirmwareFile.Sha(checkedFile.Inflated)==PublicFirmware.PayloadHash);});
   test("wrong_stock_is_rejected_before_rebuild",()=>{bool rejected=false;try{PublicFirmware.Apply(new byte[128],patch);}catch(InvalidDataException){rejected=true;}need(rejected);});
   test("tampered_recipe_is_rejected",()=>{var json=new JavaScriptSerializer{MaxJsonLength=4*1024*1024};var recipe=json.Deserialize<PublicFirmware.Recipe>(System.Text.Encoding.UTF8.GetString(patch));recipe.records[0].target_sha256=new string('0',64);bool rejected=false;try{PublicFirmware.Apply(File.ReadAllBytes(official),System.Text.Encoding.UTF8.GetBytes(json.Serialize(recipe)));}catch(InvalidDataException){rejected=true;}need(rejected);});
  }
  File.WriteAllText(Path.Combine(folder,"results.json"),new JavaScriptSerializer().Serialize(new{status=failed==0?"PASS_OFFLINE_ONLY":"FAIL",cases=cases,NAM_fixture_cases=33,USB_opened=false,SDK_started=false,physical_installation_tested=false}));return failed==0?0:1;
 }
 static IEnumerable<Control> Children(Control root){foreach(Control child in root.Controls){yield return child;foreach(var sub in Children(child))yield return sub;}}
 static void Field(object o,string n,object v){o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(o,v);}
 static object Call(object o,string n,params object[] args){try{return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,args);}catch(TargetInvocationException e){throw e.InnerException??e;}}
}
